<?php
declare(strict_types=1);require_once __DIR__.'/../src/db.php';require_once __DIR__.'/../src/auth.php';require_login();$pdo=db();$id=$_GET['id']??'';
$q=$pdo->prepare("SELECT s.*,sp.overall_level,sp.estimated_level,sp.goal,sp.correction_mode,sp.diagnostic_status,sp.diagnostic_step,COALESCE(sp.grammar_score,0) grammar_score,COALESCE(sp.vocabulary_score,0) vocabulary_score,COALESCE(sp.speaking_score,0) speaking_score,COALESCE(sp.listening_score,0) listening_score,COALESCE(sp.reading_score,0) reading_score,COALESCE(sp.writing_score,0) writing_score,COALESCE(sp.fluency_score,0) fluency_score,COALESCE(sp.pronunciation_score,0) pronunciation_score,COALESCE(sp.xp,0) xp,COALESCE(sp.streak_days,0) streak_days,sp.last_study_at FROM students s LEFT JOIN student_profiles sp ON sp.student_id=s.id WHERE s.id=:id");$q->execute(['id'=>$id]);$student=$q->fetch();if(!$student){http_response_code(404);exit('Aluno não encontrado.');}
$q=$pdo->prepare("SELECT * FROM student_errors WHERE student_id=:id AND status='learning' ORDER BY occurrences DESC,mastery_score ASC LIMIT 10");$q->execute(['id'=>$id]);$errors=$q->fetchAll();
$q=$pdo->prepare("SELECT v.word,v.translation,v.example,sv.mastery_score,sv.next_review_at,sv.status FROM student_vocabulary sv JOIN vocabulary v ON v.id=sv.vocabulary_id WHERE sv.student_id=:id AND sv.status IN ('learning','review') ORDER BY CASE WHEN sv.next_review_at IS NULL OR sv.next_review_at<=NOW() THEN 0 ELSE 1 END,sv.next_review_at NULLS FIRST LIMIT 12");$q->execute(['id'=>$id]);$vocab=$q->fetchAll();
$q=$pdo->prepare("SELECT COUNT(*) FILTER(WHERE status='mastered') mastered,COUNT(*) FILTER(WHERE status IN ('learning','review')) learning,COUNT(*) FILTER(WHERE status IN ('learning','review') AND (next_review_at IS NULL OR next_review_at<=NOW())) due FROM student_vocabulary WHERE student_id=:id");$q->execute(['id'=>$id]);$vocabStats=$q->fetch();
$q=$pdo->prepare("SELECT COUNT(*) FROM student_errors WHERE student_id=:id AND status='learning' AND (next_review_at IS NULL OR next_review_at<=NOW())");$q->execute(['id'=>$id]);$errorDue=(int)$q->fetchColumn();
$q=$pdo->prepare("SELECT created_at,mode,topic,grammar_score,vocabulary_score,fluency_score FROM sessions WHERE student_id=:id ORDER BY created_at DESC LIMIT 8");$q->execute(['id'=>$id]);$sessions=$q->fetchAll();
$q=$pdo->prepare("SELECT ar.*,a.title FROM assessment_results ar LEFT JOIN assessments a ON a.id=ar.assessment_id WHERE ar.student_id=:id ORDER BY ar.created_at DESC LIMIT 1");$q->execute(['id'=>$id]);$assessment=$q->fetch()?:null;
$q=$pdo->prepare("SELECT * FROM study_plans WHERE student_id=:id AND status='active' ORDER BY created_at DESC LIMIT 1");$q->execute(['id'=>$id]);$plan=$q->fetch()?:null;$planData=$plan?(json_decode($plan['plan_data']??'{}',true)?:[]):[];
$skills=['Grammar'=>$student['grammar_score'],'Vocabulary'=>$student['vocabulary_score'],'Speaking'=>$student['speaking_score'],'Listening / Comprehension'=>$student['listening_score'],'Reading'=>$student['reading_score'],'Writing'=>$student['writing_score'],'Fluency'=>$student['fluency_score'],'Pronunciation'=>$student['pronunciation_score']];$pageTitle=$student['name'];require __DIR__.'/../templates/header.php';?>
<section class="student-head"><div><span class="badge dark"><?=htmlspecialchars($student['overall_level']??'A1')?></span><h2><?=htmlspecialchars($student['name'])?></h2><div class="label"><?=htmlspecialchars($student['phone']??'')?></div><div style="margin-top:12px"><?=htmlspecialchars($student['goal']??'Aprender inglês')?></div></div><div><div style="font-size:28px;font-weight:900"><?=(int)$student['xp']?> XP</div><div class="label"><?=(int)$student['streak_days']?> dias de sequência</div><div class="label" style="margin-top:8px"><?=$student['last_study_at']?'Último estudo: '.date('d/m H:i',strtotime($student['last_study_at'])):'Ainda sem sessão'?></div></div></section>
<section class="cards"><div class="card"><div class="label">Nível atual</div><div class="metric"><?=htmlspecialchars($student['overall_level']??'A1')?></div><div class="metric-sub">Meta: <?=htmlspecialchars($plan['target_level']??'-')?></div></div><div class="card"><div class="label">Vocabulário em estudo</div><div class="metric"><?=(int)($vocabStats['learning']??0)?></div><div class="metric-sub"><?=(int)($vocabStats['mastered']??0)?> palavras dominadas</div></div><div class="card"><div class="label">Revisões de hoje</div><div class="metric"><?=((int)($vocabStats['due']??0)+$errorDue)?></div><div class="metric-sub"><?=(int)($vocabStats['due']??0)?> palavras + <?=$errorDue?> gramática</div></div><div class="card"><div class="label">Diagnóstico</div><div class="metric" style="font-size:22px"><?=htmlspecialchars($student['diagnostic_status']??'pending')?></div><div class="metric-sub"><?=$assessment?'Última nota: '.number_format((float)$assessment['total_score'],0).'%':'Aguardando conclusão'?></div></div></section>
<div class="grid-2"><section class="panel"><h2>Competências</h2><?php foreach($skills as $name=>$score):?><div class="skill"><div class="skill-head"><span><?=htmlspecialchars($name)?></span><strong><?=number_format((float)$score,0)?>%</strong></div><div class="progress"><span data-progress="<?=(float)$score?>"></span></div></div><?php endforeach;?></section><section class="panel"><h2>Revisões prioritárias</h2><div class="review-grid"><div class="review-card"><div class="label">Palavras</div><div class="big"><?=(int)($vocabStats['due']??0)?></div></div><div class="review-card"><div class="label">Gramática</div><div class="big"><?=$errorDue?></div></div><div class="review-card"><div class="label">Total</div><div class="big"><?=((int)($vocabStats['due']??0)+$errorDue)?></div></div></div><h3>Vocabulário mais próximo</h3><?php if(!$vocab):?><div class="label">Nenhuma palavra registrada ainda.</div><?php endif;?><?php foreach(array_slice($vocab,0,5) as $item):?><div class="list-card"><strong><?=htmlspecialchars($item['word'])?></strong><?php if($item['translation']):?> <span class="badge"><?=htmlspecialchars($item['translation'])?></span><?php endif;?><p>Domínio: <?=number_format((float)$item['mastery_score'],0)?>%<?=$item['next_review_at']?' · revisão '.date('d/m H:i',strtotime($item['next_review_at'])):''?></p></div><?php endforeach;?></section></div>
<div class="grid-2" style="margin-top:20px"><section class="panel"><h2>Pontos que mais precisam de atenção</h2><?php if(!$errors):?><div class="label">Nenhum erro recorrente registrado.</div><?php endif;?><?php foreach($errors as $e):?><div class="list-card"><div style="display:flex;justify-content:space-between"><strong><?=htmlspecialchars($e['topic']?:$e['category']?:'Correção')?></strong><span class="badge warning"><?=(int)$e['occurrences']?>x</span></div><p><?=htmlspecialchars($e['original_text']??'')?><?=$e['corrected_text']?' → '.htmlspecialchars($e['corrected_text']):''?></p><div class="progress" style="margin-top:10px"><span data-progress="<?=(float)$e['mastery_score']?>"></span></div></div><?php endforeach;?></section><section class="panel"><h2>Plano de estudo</h2><?php if(!$plan):?><div class="label">O plano será criado após o diagnóstico.</div><?php else:?><p><strong>Objetivo:</strong> <?=htmlspecialchars($plan['goal']??'')?></p><p><strong>Meta:</strong> <span class="badge"><?=htmlspecialchars($plan['target_level']??'')?></span></p><?php if(!empty($planData['focus'])):?><h3>Foco atual</h3><?php foreach($planData['focus'] as $item):?><div class="list-card"><strong><?=htmlspecialchars((string)$item)?></strong></div><?php endforeach;?><?php endif;?><?php for($w=1;$w<=4;$w++):$key='week_'.$w;if(!empty($planData[$key])):?><h3>Semana <?=$w?></h3><?php foreach($planData[$key] as $item):?><div class="list-card"><p style="margin:0"><?=htmlspecialchars((string)$item)?></p></div><?php endforeach;?><?php endif;endfor;?><?php endif;?></section></div>
<section class="panel" style="margin-top:20px"><h2>Sessões recentes</h2><div class="table-wrap"><table><thead><tr><th>Data</th><th>Modo</th><th>Tópico</th><th>Grammar</th><th>Vocabulary</th><th>Fluency</th></tr></thead><tbody><?php foreach($sessions as $s):?><tr><td><?=date('d/m/Y H:i',strtotime($s['created_at']))?></td><td><span class="badge"><?=htmlspecialchars($s['mode']??'-')?></span></td><td><?=htmlspecialchars($s['topic']??'-')?></td><td><?=$s['grammar_score']!==null?number_format((float)$s['grammar_score'],0).'%':'-'?></td><td><?=$s['vocabulary_score']!==null?number_format((float)$s['vocabulary_score'],0).'%':'-'?></td><td><?=$s['fluency_score']!==null?number_format((float)$s['fluency_score'],0).'%':'-'?></td></tr><?php endforeach;?></tbody></table></div></section><?php require __DIR__.'/../templates/footer.php';?>
